                    call_go:                `Go — pay the asking price; the strategic logic justifies the premium`,
                    call_walk:              `Walk / pivot mode — the synergy bridge can't clear €12M at this price`,

                    r3_depth_label:         `Integration depth on the preservation→absorption spectrum (0 = fully standalone unit, 100 = full absorption in 6 months)`,
                    r3_depth_readout:       `Integration depth:`,
                    r3_retention_label:     `Talent-retention & cultural-fit plan for the 60 research-led engineers (the asset you bought)`,
                    ret_package:            `Retention packages + autonomy guarantees + acquired-side leads combined eng org`,
                    ret_autonomy:           `Autonomy guarantees only — protect the culture, no cash incentives`,
                    ret_standard:           `Standard onboarding — fold them into Atlântica's HR model and processes`,
                    ret_none:               `No special plan — the technology transfers regardless of who stays`,
                    r3_bridge_label:        `The integration mechanism that actually CAPTURES the synergy without breaking the culture`,
                    bridge_jointpod:        `A joint product pod — Atlântica + NordCast engineers ship the combined module together`,
                    bridge_api:             `An API integration layer — connect the platforms, keep the teams separate`,
